    std::vector<std::string> out;
    for (Item item : items)
        if (item.weight > limit) out.push_back(item.name);
    return out;
}

int weight_of(std::map<std::string, Item> index, std::string key) {
    if (index.count(key) == 0) return -1;
    Item found = index[key];
    return found.weight;
}

